static const size_t GraphemeIncbRangesCount = 403;

static uint8_t GraphemeLookup8(const GraphemeRange8 *ranges,
                                     size_t count,
                                     uint32_t cp,
                                     uint8_t defaultVal)
{
    size_t lo = 0, hi = count;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        const GraphemeRange8 *r = &ranges[mid];
        if (cp < r->start) {
            hi = mid;
        } else if (cp > r->end) {
            lo = mid + 1u;
        } else {
            return r->value;
        }
    }
    return defaultVal;
}

UnicodeGraphemeBreak GraphemeBreakProperty(Uchar32 cp)
{
    return (UnicodeGraphemeBreak)GraphemeLookup8(
        GraphemeGbRanges, GraphemeGbRangesCount, cp, 0);
}

UnicodeIncb GraphemeIncb(Uchar32 cp)
{
    return (UnicodeIncb)GraphemeLookup8(
        GraphemeIncbRanges, GraphemeIncbRangesCount, cp, 0);
}

